<?php
declare(strict_types=1);

/**
 * Search index endpoint
 *
 * Serves the compact index generated by bin/build.php. The browser downloads
 * it once (cached + ETag) and every search then runs client-side, so typing
 * in the search box costs the server nothing.
 *
 * @endpoint GET /api/search-index.php
 */

require_once __DIR__ . '/../src/api/autoload.php';

use MotorsportDB\API\Data\Database;

ini_set('display_errors', '0');
$file = Database::varDir() . '/search-index.json';
if (!is_file($file)) {
    http_response_code(503);
    header('Content-Type: application/json');
    echo '{"error":"Search index not built"}';
    exit;
}

$etag = '"' . hash('xxh128', filemtime($file) . ':' . filesize($file)) . '"';
header('Content-Type: application/json; charset=UTF-8');
header('X-Content-Type-Options: nosniff');
header('Cache-Control: public, max-age=3600, stale-while-revalidate=86400');
header('ETag: ' . $etag);
if (trim($_SERVER['HTTP_IF_NONE_MATCH'] ?? '') === $etag) {
    http_response_code(304);
    exit;
}
header('Content-Length: ' . filesize($file));
readfile($file);
